simulation/referee.py:
"""Juez del simulador: revisa cada misión con las condiciones del reglamento.

Es independiente del programa del robot: el programa cree que logró una misión cuando sus pasos
terminan bien; el juez mira dónde quedó el robot y los objetos. Las dos columnas se comparan en
el reporte.

Interpretaciones (TODO confirmar con el reglamento o en la junta de capitanes):
- Misiones 2 y 8, "al menos a 5 cm de distancia de la base": la base del objeto queda >= 5 cm
  arriba de la cara superior del pedestal.
- "Completamente dentro" de un nivel: las cuatro esquinas de las orugas sobre la parte plana.
- Misión 11: cuenta los colores de tarjeta distintos que el robot mostró en la pantalla.
"""

import arena as ar

LIFT_CM = 5.0
HOLD_S = 5.0


class Referee:
    def __init__(self, sim, missions, start_level=1):
        self.sim = sim
        # al reiniciar en un nivel, las misiones de niveles anteriores no se juegan
        self.pts = {m["id"]: m["pts"] for m in missions if m["level"] >= start_level}
        self.done = {}              # id -> tiempo en que se logró
        self.hold = {"cube": None, "ball": None}
        self.in_room = False
        self.shown = []             # colores mostrados en pantalla (línea 3)
        self._last_label = None
        self.touched_tower = False

    # ------------------------------------------------------------ ayudas
    def _corners_on(self, level):
        s = self.sim
        return all(s.arena.surface(x, y) == level for x, y in s.footprint())

    def _latch(self, mid):
        if mid in self.pts and mid not in self.done:
            self.done[mid] = self.sim.world.t
            self.sim.log.append((self.sim.world.t, "JUEZ: mision %d lograda" % mid))

    def _stopped(self):
        return abs(self.sim.vl) < 0.5 and abs(self.sim.vr) < 0.5

    def _lifted(self, name, ped):
        s = self.sim
        o = s.objects[name]
        if not o["held"]:
            return False
        r = s.arena.props[ped][0]
        top = (s.arena.height((r[0] + r[2]) / 2, (r[1] + r[3]) / 2) or 0) + ar.PEDESTAL_H
        return o["z"] - o["size"] / 2 >= top + LIFT_CM

    # ------------------------------------------------------------ cada cuadro
    def update(self):
        s = self.sim
        t = s.world.t
        a = s.arena
        if self._stopped() and ar.inside(a.m1_zone, s.x, s.y):
            self._latch(1)
        for mid, name, ped in ((2, "cube", "pedestal1"), (8, "ball", "ball_ped")):
            if self._lifted(name, ped):
                if self.hold[name] is None:
                    self.hold[name] = t
                elif t - self.hold[name] >= HOLD_S:
                    self._latch(mid)
            else:
                self.hold[name] = None
        for mid, lvl in ((3, 2), (6, 3), (9, 4)):
            # colocado ahí por un reinicio no cuenta: hay que haberlo subido
            if mid not in self.done and lvl > s.placed_level and self._corners_on(lvl):
                self._latch(mid)
        if ar.inside(a.room, s.x, s.y):
            self.in_room = True
        elif self.in_room and s.x > a.room[2]:
            fp = s.footprint()
            if all(not ar.inside(a.room, x, y) for x, y in fp):
                self._latch(5)
        tower = a.props["tower"][0]
        if a.surface(s.x, s.y) == 4 and all(x < tower[0] for x, _ in s.footprint()):
            self._latch(10)
        if "tower" in s.contacts:
            self.touched_tower = True
        lab = s.world.labels.get(3)
        if lab and lab != self._last_label:
            self._last_label = lab
            self.shown.append(lab.strip().lower())

    # ------------------------------------------------------------ al terminar
    def end_state(self):
        """Misiones que se juzgan por cómo QUEDAN las cosas (cubo, prisma, pelota, meta)."""
        s = self.sim
        a = s.arena
        ids = set()
        if s.objects["cube"]["on"] == "pedestal2" and not s.objects["cube"]["held"]:
            ids.add(4)
        pr = s.prism
        if not pr["lost"]:
            h = pr["half"]
            d = a.dotted
            if pr["x"] + h > d[0] and pr["x"] - h < d[2] and pr["y"] + h > d[1] and pr["y"] - h < d[3]:
                ids.add(7)
        red = [i for i, (_, c) in enumerate(a.cards) if c == "red"]
        if red and s.objects["ball"]["on"] == "hole%d" % red[0]:
            ids.add(12)
        goal = a.zones[4][1]
        if self._stopped() and not s.fallen and all(ar.inside(goal, x, y) for x, y in s.footprint()):
            ids.add(13)
        return ids

    def snapshot(self):
        """Estado del juez sin cerrar la corrida (para el simulador en vivo)."""
        ok = set(self.done) | self.end_state()
        cards = set(self.sim.arena.card_colors)
        seen = set(c for c in self.shown if c in cards)
        out = []
        for mid in sorted(self.pts):
            good = (len(seen) > 0) if mid == 11 else (mid in ok)
            p = 20 * len(seen) if mid == 11 else (self.pts[mid] if good else 0)
            out.append({"id": mid, "ok": good, "pts": p})
        return out

    def final(self):
        s = self.sim
        a = s.arena
        for mid in self.end_state():
            self._latch(mid)
        cards = set(a.card_colors)
        seen = sorted(set(c for c in self.shown if c in cards))
        out = []
        total = 0
        falls = getattr(s, "falls", 0) + (1 if s.fallen else 0)
        penalty = 20 * max(0, falls - 1)        # la primera falta es advertencia
        for mid in sorted(self.pts):
            if mid == 11:
                p = 20 * len(seen)
                ok = len(seen) > 0
            else:
                ok = mid in self.done
                p = self.pts[mid] if ok else 0
            total += p
            out.append({"id": mid, "ok": ok, "pts": p, "t": self.done.get(mid)})
        notes = []
        cols = getattr(s, "collisions", {})
        if cols:
            notes.append("choques: " + ", ".join("%s %d" % (k, v) for k, v in sorted(cols.items())))
        if s.fallen:
            notes.append("CAÍDA: " + s.fallen)
        notes_tip = s.min_tip
        if s.slides:
            notes.append("se resbaló hacia atrás en una pendiente %d vez/veces" % s.slides)
        if falls:
            notes.append("caídas: %d (penalización %d)" % (falls, penalty))
        restarts = getattr(s, "restarts", [])
        if restarts:
            notes.append("reinicios: %s" % ", ".join("nivel %d" % lv for lv in restarts))
        return {"missions": out, "total": total - penalty, "cards_seen": seen, "notes": notes,
                "min_tip_cm": round(notes_tip, 1), "restarts": len(restarts), "falls": falls}

simulation/userprog.py:
"""Correr en el simulador un programa SUBIDO por el usuario (.py o .mblock en modo Python).

Programas como los del equipo (FuncionesEnPython.mblock, calibrations.py) usan el módulo
`event` de mBlock: @event.start y @event.is_press('a') corren EN PARALELO en el CyberPi. Aquí
cada manejador es un hilo y todos comparten un reloj simulado: la física avanza solo cuando
TODOS los hilos del programa están esperando (time.sleep), hasta el que despierta primero.
Así el resultado no depende de la velocidad de la PC.

Módulos disponibles para el programa: cyberpi, mbot2, mbuild, gamepad, event, time, math,
random y los del proyecto (hal, config, motion, ...).
"""

import io
import json
import sys
import threading
import time
import types
import zipfile

REAL_SLEEP = time.sleep
REAL_TIME = time.time


class Stop(BaseException):
    """Termina los hilos del programa (nueva corrida). El código del robot no la atrapa."""


def source_from_upload(name, data):
    """Bytes de un .py o .mblock -> (código Python, descripción). Lanza ValueError si no hay
    código Python (un .mblock solo de bloques)."""
    if name.lower().endswith(".mblock") or data[:2] == b"PK":
        try:
            z = zipfile.ZipFile(io.BytesIO(data))
            proj = json.loads(z.read("project.json").decode("utf-8"))
        except (zipfile.BadZipFile, KeyError, ValueError) as e:
            raise ValueError("no es un .mblock válido (%s)" % e)
        best = None
        for t in proj.get("targets", []):
            code = (t.get("codes") or {}).get("python") or ""
            if code.strip() and (best is None or len(code) > len(best[1])):
                best = (t.get("name", "?"), code)
        if best is None:
            nb = sum(len(t.get("blocks") or {}) for t in proj.get("targets", []))
            raise ValueError("el .mblock no tiene código Python (%d bloques). Por ahora el "
                             "simulador corre programas en modo Python." % nb)
        return best[1], "%s (objeto '%s' del .mblock)" % (name, best[0])
    try:
        return data.decode("utf-8"), name
    except UnicodeDecodeError:
        return data.decode("latin-1"), name


class Runner:
    """Hilos del programa + reloj simulado. `step(dt)` avanza la física (lo da la sesión)."""

    def __init__(self, world, step, log, on_idle=None, speed=lambda: 1.0, paused=lambda: False):
        self.world = world
        self.step = step                # avanza la física dt segundos
        self.log = log
        self.on_idle = on_idle          # se llama en cada vuelta del reloj (botones, reinicios)
        self.speed = speed
        self.paused = paused
        self.cv = threading.Condition()
        self.wake = {}                  # id de hilo -> hora de despertar (None = corriendo)
        self.names = {}
        self.stop = False
        self.start_handlers = []
        self.press_handlers = {}        # botón -> función
        self.running_press = set()
        self._prev_pressed = set()
        self.error = None

    # ------------------------------------------------------------ reloj
    def mine(self):
        return threading.get_ident() in self.wake

    def sleep(self, dt):
        if not self.mine():
            return REAL_SLEEP(dt)
        me = threading.get_ident()
        with self.cv:
            self.wake[me] = self.world.t + max(0.0, dt)
            self.cv.notify_all()
            while self.wake.get(me) is not None:
                if self.stop:
                    raise Stop()
                self.cv.wait(0.05)
        if self.stop:
            raise Stop()

    def now(self):
        return self.world.t if self.mine() else REAL_TIME()

    def _spawn(self, fn, name):
        started = threading.Event()

        def body():
            me = threading.get_ident()
            with self.cv:
                self.wake[me] = None
                self.names[me] = name
            started.set()
            try:
                fn()
            except Stop:
                pass
            except Exception as e:          # noqa: BLE001 - se informa al usuario
                self._report(name, e)
            finally:
                with self.cv:
                    self.wake.pop(me, None)
                    self.names.pop(me, None)
                    self.running_press.discard(name)
                    self.cv.notify_all()
        th = threading.Thread(target=body, daemon=True)
        th.start()
        started.wait(2)

    def _report(self, name, e):
        import traceback
        tb = traceback.extract_tb(e.__traceback__)
        where = ""
        for fr in reversed(tb):
            if fr.filename == "programa":
                where = " (línea %d)" % fr.lineno
                break
        self.log.append((self.world.t, "ERROR en %s%s: %s: %s" % (name, where, type(e).__name__, e)))
        if self.error is None:
            self.error = "%s%s: %s" % (type(e).__name__, where, e)

    def clock_loop(self):
        """Hilo del reloj: espera a que todos los hilos duerman y avanza la física."""
        while not self.stop:
            while self.paused() and not self.stop:
                REAL_SLEEP(0.05)
            with self.cv:
                deadline = REAL_TIME() + 2.0
                while any(w is None for w in self.wake.values()) and not self.stop:
                    self.cv.wait(0.02)
                    if REAL_TIME() > deadline:       # un hilo que no duerme (bucle sin sleep)
                        break
                pending = [w for w in self.wake.values() if w is not None]
            target = min(pending) if pending else self.world.t + 0.02
            dt = max(0.0, min(target - self.world.t, 0.1))
            if dt > 0:
                self.step(dt)
                REAL_SLEEP(dt / max(0.1, self.speed()))
            else:
                REAL_SLEEP(0)
            if self.on_idle:
                self.on_idle()
            self._buttons()
            with self.cv:
                for k, w in list(self.wake.items()):
                    if w is not None and w <= self.world.t + 1e-9:
                        self.wake[k] = None
                self.cv.notify_all()

    def _buttons(self):
        now = set(self.world.pressed)
        for k in now - self._prev_pressed:
            fn = self.press_handlers.get(k)
            if fn is not None and k not in self.running_press:
                self.running_press.add(k)
                self._spawn(fn, k)
        self._prev_pressed = now

    # ------------------------------------------------------------ programa
    def event_module(self):
        ev = types.ModuleType("event")
        runner = self

        def start(fn):
            runner.start_handlers.append(fn)
            return fn

        def is_press(key):
            def deco(fn):
                runner.press_handlers[key] = fn
                return fn
            return deco

        def noop(*a, **k):
            if a and callable(a[0]):
                return a[0]
            return lambda fn: fn
        ev.start = start
        ev.is_press = is_press
        for n in ("is_release", "greater_than", "smaller_than", "receive", "is_shake",
                  "is_tiltleft", "is_tiltright", "is_tiltforward", "is_tiltback"):
            setattr(ev, n, noop)
        return ev

    def run(self, source):
        """Ejecuta el programa: el cuerpo del archivo en un hilo; al terminar, los
        manejadores @event.start (cada uno en su hilo)."""
        sys.modules["event"] = self.event_module()
        code = compile(source, "programa", "exec")
        ns = {"__name__": "__main__"}

        def body():
            exec(code, ns)
            for i, fn in enumerate(list(self.start_handlers)):
                self._spawn(fn, "inicio %d" % (i + 1))
        self._spawn(body, "programa")
        self.clock_loop()

