# Rover X 2026: reconocimiento de colores (zonas de inicio, marcas verdes, tarjetas).

import hal
import config as cfg

# Color para LEDs del CyberPi (misión 11: mostrar el color reconocido)
LED_RGB = {
    "black": (0, 0, 0),
    "white": (255, 255, 255),
    "red": (255, 0, 0),
    "yellow": (255, 200, 0),
    "green": (0, 255, 0),
    "blue": (0, 0, 255),
    "cyan": (0, 255, 255),
    "purple": (180, 0, 255),
}


def nearest(rgb, refs):
    """Nombre del color de referencia más cercano (distancia sobre cromaticidad + brillo).

    Normalizar por el brillo hace la clasificación menos sensible a cambios de luz
    (reglamento: el robot debe adaptarse a la iluminación)."""
    r, g, b = rgb
    total = r + g + b + 1
    best = None
    best_d = None
    for name in refs:
        rr, rg, rb = refs[name]
        rt = rr + rg + rb + 1
        dc = (r / total - rr / rt) ** 2 + (g / total - rg / rt) ** 2 + (b / total - rb / rt) ** 2
        db = ((total - rt) / 765.0) ** 2
        d = dc * 4 + db
        if best_d is None or d < best_d:
            best = name
            best_d = d
    return best


def normalize(name):
    """Nombres del sensor -> nombres del programa (el sensor puede devolver mayúsculas)."""
    if name is None:
        return "unknown"
    return str(name).strip().lower()


def read(probe):
    if cfg.P["color_mode"] == 1:
        return nearest(hal.probe_rgb(probe), cfg.COLOR_REF)
    return normalize(hal.probe_color_builtin(probe))


def read_stable(probe, n=None):
    """Lee hasta tener n lecturas iguales seguidas (máx. 4n intentos)."""
    if n is None:
        n = cfg.COLOR_CONFIRM
    last = None
    count = 0
    for _ in range(n * 4):
        c = read(probe)
        if c == last:
            count += 1
        else:
            last = c
            count = 1
        if count >= n:
            return c
        hal.wait(cfg.LOOP_DT)
    return last


def show(name):
    rgb = LED_RGB.get(name, (40, 40, 40))
    hal.leds(rgb[0], rgb[1], rgb[2])
    hal.show(name, line=3, size=24)


def zone_level(color):
    """Nivel de inicio según el color de la zona en la que está el robot (0 = no se sabe)."""
    return cfg.ZONE_LEVEL.get(color, 0)


def is_card_color(name):
    """Una tarjeta es cualquier color que no sea el piso blanco ni la línea negra."""
    return name not in ("white", "black", "unknown", "")

software/core/geometry.py:
# Rover X 2026: cuentas que dependen de la geometría del robot (cfg.P).
#
# Así, cambiar la geometría (otro chasis, otra garra, el sensor más adelante) solo requiere
# medir de nuevo y ajustar cfg.P; las misiones no cambian. Esquema en docs/geometria.md.
# Los parámetros "_fwd" se miden desde el punto de referencia (sobre la caja del mBot2); aquí
# se convierten al CENTRO DE GIRO (punto medio de las orugas). Todo en cm.

import math
import config as cfg

def p(key):
    return cfg.P[key]


def fwd(key):
    """Distancia hacia adelante desde el CENTRO DE GIRO de un punto medido desde la referencia."""
    return p(key) - p("ref_rot_fwd")


def track_w():
    """Distancia entre los centros de las dos orugas."""
    return p("robot_w") - p("belt_w")


def contact_half():
    """Del centro de giro a cada extremo del tramo apoyado (eje blanco / eje 1a negra)."""
    return p("track_c") / 2.0


def nose_fwd():
    """Del centro de giro al eje de la rueda de la nariz (horizontal)."""
    return contact_half() + p("track_d") * math.cos(math.radians(p("nose_deg")))


def nose_h():
    """Altura del eje de la nariz sobre los ejes apoyados (cm)."""
    return p("track_d") * math.sin(math.radians(p("nose_deg")))


def rear_len():
    """Del centro de giro a la parte trasera (punta trasera de las orugas)."""
    return contact_half() + p("wheel_d") / 2.0 + p("belt_t")


def track_front():
    """Del centro de giro a la punta delantera de las orugas (la nariz)."""
    return nose_fwd() + p("wheel_d") / 2.0 + p("belt_t")


def track_len():
    """Largo de la oruga de punta a punta, visto desde arriba."""
    return rear_len() + track_front()


def front_len():
    """Del centro de giro a lo más adelantado del robot (oruga o garra en posición de viaje)."""
    claw = claw_reach(p("h_carry")) + p("claw_tip")
    track = track_front()
    return claw if claw > track else track


def robot_len():
    return rear_len() + front_len()


def cm_per_deg():
    """cm que avanza la oruga por grado de encoder."""
    return math.pi * p("sprocket_d") / 360.0 * p("slip")


def cm_per_deg_lr():
    """(izquierda, derecha): cm por grado de cada oruga. No avanzan igual por grado (prueba de
    1 m: 63.5 y 65); su promedio es cm_per_deg()."""
    k = cm_per_deg()
    r = p("lr_ratio")
    return k * 2.0 * r / (1.0 + r), k * 2.0 / (1.0 + r)


# ---------------------------------------------------------------- brazo (tabla medida)
ARM_ANGLES = (0, 45, 90)     # ángulos del servo de la tabla (fotos); fuera de 0..90 no se usa


def _arm_rows():
    return ((0, p("arm_h0"), p("arm_x0")), (45, p("arm_h45"), p("arm_x45")),
            (90, p("arm_h90"), p("arm_x90")))


def arm_at(servo):
    """(altura de la garra sobre el piso, cm delante de la nariz) con el servo a ese ángulo."""
    rows = _arm_rows()
    if servo <= rows[0][0]:
        return rows[0][1], rows[0][2]
    for i in range(len(rows) - 1):
        a0, h0, x0 = rows[i]
        a1, h1, x1 = rows[i + 1]
        if servo <= a1:
            f = (servo - a0) / float(a1 - a0)
            return h0 + f * (h1 - h0), x0 + f * (x1 - x0)
    return rows[-1][1], rows[-1][2]


def arm_servo(h):
    """Ángulo del servo del brazo para la altura h (cm sobre el piso); fuera del alcance, el tope."""
    rows = _arm_rows()
    if h <= rows[0][1]:
        return rows[0][0]
    for i in range(len(rows) - 1):
        a0, h0, _ = rows[i]
        a1, h1, _ = rows[i + 1]
        if h <= h1:
            return a0 + (h - h0) / (h1 - h0) * (a1 - a0)
    return rows[-1][0]


def claw_reach(h):
    """Distancia horizontal del centro de giro al centro de la garra, con la garra a la altura h."""
    return track_front() + arm_at(arm_servo(h))[1]


# ---------------------------------------------------------------- distancias de maniobra
def turn_advance():
    """Lo que hay que avanzar tras detectar un cruce con las sondas para girar SOBRE él."""
    return fwd("sensor_fwd")


def reach_advance(target, h):
    """Avance para que el punto de agarre (garra a la altura h) llegue a un objeto cuyo centro
    está a `target` cm del centro de giro, en la dirección en la que mira el robot."""
    return target - claw_reach(h)


def pedestal_advance(h, from_cross, traveled):
    """Sin ultrasónico: avance para dejar la garra sobre el centro de un pedestal que está a
    `from_cross` cm de un cruce, cuando el robot ya avanzó `traveled` cm desde que las sondas
    detectaron ese cruce (en ese momento el centro de giro estaba sensor_fwd atrás)."""
    return from_cross - claw_reach(h) + fwd("sensor_fwd") - traveled


def tower_advance(traveled):
    """Avance (siguiendo la línea) hasta quedar a side_margin de la torre, medido desde que las
    sondas salieron de la zona verde y ya se avanzaron `traveled` cm."""
    return p("tower_from_edge") - front_len() - p("side_margin") + fwd("sensor_fwd") - traveled


def ramp_extra():
    """Avance después de quedar plano arriba de una rampa para estar completamente dentro."""
    return rear_len() + p("ramp_margin")


def zone_extra():
    """Avance desde que las sondas entran a una zona hasta que todo el robot está dentro."""
    return fwd("sensor_fwd") + rear_len() + p("ramp_margin")


def detour_out():
    """Desplazamiento lateral para rodear la torre sin tocarla."""
    return p("robot_w") / 2.0 + p("tower_size") / 2.0 + p("side_margin")


def detour_pass():
    """Avance paralelo para rebasar la torre por completo, partiendo de side_margin antes de ella."""
    return front_len() + p("tower_size") + rear_len() + 2 * p("side_margin")


def card_to_center(card_odo, now_odo):
    """Cuánto moverse (cm, negativo = atrás) para dejar el centro de giro frente a una tarjeta
    detectada cuando la odometría marcaba card_odo."""
    return card_odo + fwd("card_probe_fwd") - now_odo


def probe_x(probe):
    """Posición lateral de cada sonda (cm, negativo = izquierda)."""
    i = cfg.PROBES.index(probe)
    return probe_lat(i, p("probe_pitch"), p("probe_outer"))


def probe_lat(i, pitch, outer):
    """Sonda i (0..3, de izquierda a derecha) -> cm laterales (no están igual de separadas)."""
    inner = pitch / 2.0
    return (-inner - outer, -inner, inner, inner + outer)[i]

software/core/hal.py:
# Rover X 2026: capa de hardware (HAL).
#
# ÚNICO lugar que llama a la API de MicroPython del mBot2 (cyberpi, mbot2, mbuild, gamepad).
# El resto del programa usa estas funciones con convenciones fijas:
#   - drive(izq, der): potencia -100..100, positivo = adelante en ambas orugas
#   - heading(): grados acumulados, positivo = giro a la DERECHA
#   - pitch(): grados, positivo = nariz ARRIBA
#   - line_offset(): -100..100, negativo = la línea está a la IZQUIERDA del centro
#   - darkness(): por sonda, 0 = blanco calibrado, 1 = negro calibrado
# Referencia de la API: docs/api_mbot2.md

import time
import cyberpi
import mbot2
import mbuild
import config as cfg
import geometry as geo

# El control Bluetooth es opcional (en PC o sin dongle no existe el módulo).
# Ojo: no asignar "gamepad = None"; el bundler renombra las variables globales.
try:
    import gamepad
    _HAS_PAD = True
except ImportError:
    _HAS_PAD = False

PROBES = cfg.PROBES

_heading_zero = 0
_odo_zero = 0
_abort = False


def clamp(v, lo, hi):
    if v < lo:
        return lo
    if v > hi:
        return hi
    return v


def init():
    global _abort
    _abort = False
    stop()
    reset_heading()
    reset_odometer()
    mbuild.quad_rgb_sensor.set_led(color="white")
    cyberpi.led.on(0, 0, 0, id="all")


# ---------------------------------------------------------------- tiempo
def now():
    return cyberpi.timer.get()


_on_wait = []            # funciones que se llaman en cada espera (p. ej. odometry.update)


def wait(s):
    for f in _on_wait:
        f()
    time.sleep(s)


# ---------------------------------------------------------------- motores
_last_cmd = [0.0, 0.0]
_last_t = 0.0
_boost = 0.0             # potencia extra de la asistencia de subida
_last_odo = 0.0


def _tip_guard(left, right):
    """Control contra volcadura. Inclinado (rampa, escalera), un arranque brusco empuja el centro
    de masa detrás de la punta de las orugas y el robot se voltea hacia atrás: la potencia solo
    puede SUBIR tip_slew %/s. Bajar la potencia siempre está permitido.

    No se recorta la potencia en pendientes fuertes: en una rampa de 40° eso dejaba al robot sin
    fuerza a media subida (lo mostró el simulador). El otro control es el brazo (gripper.climb_pose)."""
    global _last_t
    t = now()
    dt = t - _last_t
    _last_t = t
    # Se limita solo la potencia COMÚN (el avance); la diferencia entre orugas (la dirección)
    # queda libre: limitarla también frenaba las correcciones de rumbo y en la escalera una oruga
    # se salía de su tramo (lo mostró el simulador).
    global _boost, _last_odo
    mean = (left + right) / 2.0
    diff = (left - right) / 2.0
    prev = (_last_cmd[0] + _last_cmd[1]) / 2.0
    odo = odo_abs()
    v = (odo - _last_odo) / dt if dt > 0.001 else 0.0
    _last_odo = odo
    if pitch() >= cfg.P["tip_pitch"] and mean > 0:
        # asistencia de subida: si con potencia hacia adelante el robot casi no avanza o se
        # resbala hacia atrás, la potencia sube de a poco (no se queda parado en la pendiente)
        if v < cfg.P["slope_min_v"]:
            _boost = clamp(_boost + cfg.P["slope_boost"] * clamp(dt, 0.0, 0.2), 0, 60)
        else:
            _boost = clamp(_boost - cfg.P["slope_boost"] * clamp(dt, 0.0, 0.2), 0, 60)
        mean = mean + _boost
    else:
        _boost = 0.0
    if abs(pitch()) >= cfg.P["tip_pitch"]:
        step = cfg.P["tip_slew"] * clamp(dt, 0.0, 0.2)
        if abs(mean) > abs(prev) + step:
            mean = prev + step if mean > prev else prev - step
    _last_cmd[0] = mean + diff
    _last_cmd[1] = mean - diff
    return mean + diff, mean - diff


def drive(left, right):
    left, right = _tip_guard(left, right)
    # prioridad a la DIRECCIÓN: si una oruga pasaría de 100 %, se bajan las dos lo mismo y la
    # diferencia (la corrección de rumbo) se conserva. Recortar solo una dejaba casi sin
    # corrección a potencia máxima: en la escalera el robot se desviaba y una oruga se salía de
    # su tramo (lo mostró el simulador).
    over = max(abs(left), abs(right)) - 100
    if over > 0:
        mean = (left + right) / 2.0
        diff = (left - right) / 2.0
        if mean > 0:
            mean -= over
        else:
            mean += over
        left = mean + diff
        right = mean - diff
    left = clamp(left, -100, 100)
    right = clamp(right, -100, 100)
    mbot2.drive_power(cfg.LEFT_SIGN * left, cfg.RIGHT_SIGN * right)


def stop():
    _last_cmd[0] = 0.0
    _last_cmd[1] = 0.0
    mbot2.drive_power(0, 0)


def _encoder_deg():
    """Avance del robot en grados de encoder, CON signo (adelante +, atrás -).

    Es el promedio de las dos orugas con su signo, así que un giro en el lugar no suma
    (antes se usaba abs() y los giros cambiaban la odometría, lo que movía las distancias
    medidas desde un cruce o una tarjeta)."""
    a = cfg.LEFT_SIGN * mbot2.EM_get_angle("EM1")
    b = cfg.RIGHT_SIGN * mbot2.EM_get_angle("EM2")
    return (a + b) / 2


def tracks_cm():
    """(izquierda, derecha): avance de cada oruga en cm desde el arranque, con signo."""
    kl, kr = geo.cm_per_deg_lr()
    return (cfg.LEFT_SIGN * mbot2.EM_get_angle("EM1") * kl,
            cfg.RIGHT_SIGN * mbot2.EM_get_angle("EM2") * kr)


def reset_odometer():
    global _odo_zero
    _odo_zero = _encoder_deg()


def odo_abs():
    """Avance absoluto (cm desde el arranque, con signo); no se reinicia."""
    return _encoder_deg() * geo.cm_per_deg()


def odometer_cm():
    """Avance (cm, con signo) desde el último reset_odometer()."""
    return (_encoder_deg() - _odo_zero) * geo.cm_per_deg()


def servo(port, angle):
    mbot2.servo_set(clamp(angle, 0, 180), port)


# ---------------------------------------------------------------- giroscopio
def _raw_heading():
    # gyro_scale: grados reales por grado que reporta el giroscopio (TODO calibrar: girar el
    # robot A MANO 360° contra una escuadra y leer get_rotation("z"); 360 / lectura)
    return cfg.HEADING_SIGN * cyberpi.get_rotation("z") * cfg.P.get("gyro_scale", 1.0)


def reset_heading():
    global _heading_zero
    _heading_zero = _raw_heading()


def heading():
    return _raw_heading() - _heading_zero


def pitch():
    return cfg.PITCH_SIGN * cyberpi.get_pitch()


# ---------------------------------------------------------------- Quad RGB
# Con línea delgada (10-30 mm) la línea puede quedar ENTRE dos sondas y el modo binario la
# pierde. En line_mode = 1 se usa la luz de cada sonda calibrada contra blanco y negro: una
# sonda medio cubierta da ~0.5 y el centro ponderado sigue siendo correcto.

def probe_light(probe):
    return mbuild.quad_rgb_sensor.get_light(probe)


def darkness():
    """Dict sonda -> 0..1 (0 = blanco, 1 = negro) según la calibración LINE_CAL."""
    out = {}
    for pr in PROBES:
        white, black = cfg.LINE_CAL[pr]
        span = white - black
        if span < 1:
            span = 1
        out[pr] = clamp((white - probe_light(pr)) / span, 0, 1)
    return out


def offset_from(dk):
    """Centro ponderado de la oscuridad -> -100..100 (función pura, probada en PC).

    Se resta el fondo (la sonda más clara): sobre una zona oscura (azul, verde) todas las sondas
    suben igual y la línea se perdía en el promedio (la curva del nivel 3 empieza dentro de la
    zona azul; lo mostró el simulador)."""
    base = 1.0
    for i in range(4):
        if dk[PROBES[i]] < base:
            base = dk[PROBES[i]]
    # posición real de cada sonda en cm (no están igual de separadas: 2.4 / 1.25 / 2.4)
    pi = cfg.P["probe_pitch"] / 2.0
    po = pi + cfg.P.get("probe_outer", cfg.P["probe_pitch"])
    lat = (-po, -pi, pi, po)
    total = 0
    acc = 0
    for i in range(4):
        d = dk[PROBES[i]] - base
        total += d
        acc += d * lat[i]
    if total < 0.05:
        return 0
    return clamp(acc / total / po * 100, -100, 100)


def line_offset():
    if cfg.P["line_mode"] == 1:
        return offset_from(darkness())
    return cfg.LINE_SIGN * mbuild.quad_rgb_sensor.get_offset_track(cfg.LINE_SENSOR)


def line_read():
    """(offset, bits) con UNA sola lectura de las sondas (para el lazo de control)."""
    if cfg.P["line_mode"] == 1:
        dk = darkness()
        th = cfg.P["dark_th"]
        bits = {}
        for pr in PROBES:
            bits[pr] = dk[pr] >= th
        # para los cruces, las exteriores piden negro "fuerte": las marcas verdes junto a la
        # línea también son oscuras y adelantaban el cruce (lo mostró el simulador)
        bits["L2x"] = dk["L2"] >= cfg.P["cross_th"]
        bits["R2x"] = dk["R2"] >= cfg.P["cross_th"]
        return offset_from(dk), bits
    return line_offset(), line_bits()


def line_bits():
    """Dict sonda -> True si ve línea negra."""
    out = {}
    if cfg.P["line_mode"] == 1:
        dk = darkness()
        th = cfg.P["dark_th"]
        for pr in PROBES:
            out[pr] = dk[pr] >= th
        return out
    sta = mbuild.quad_rgb_sensor.get_line_sta("all", cfg.LINE_SENSOR)
    for pr in PROBES:
        out[pr] = (sta & cfg.LINE_BIT[pr]) != 0
    return out


def probe_rgb(probe):
    q = mbuild.quad_rgb_sensor
    return (q.get_red(probe), q.get_green(probe), q.get_blue(probe))


def probe_color_builtin(probe):
    return mbuild.quad_rgb_sensor.get_color_sta(probe)


# ---------------------------------------------------------------- ultrasónico (opcional)
def distance_cm():
    """Distancia del Ultrasónico 2, o -1 si el robot no lo lleva (HAS_US = False)."""
    if not cfg.HAS_US:
        return -1
    return mbuild.ultrasonic2.get(index=cfg.US_SENSOR)


# ---------------------------------------------------------------- CyberPi: botones, pantalla, LEDs
def button(name):
    return cyberpi.controller.is_press(name)


def abort_requested():
    """Botón de abortar (cfg.ABORT_BUTTON) = detener el autónomo (para pedir reinicio)."""
    global _abort
    if not _abort and cyberpi.controller.is_press(cfg.ABORT_BUTTON):
        _abort = True
    return _abort


def clear_abort():
    global _abort
    _abort = False


def show(text, line=0, size=16):
    cyberpi.display.show_label(text, size, 0, line * 18, index=line)


def leds(r, g, b):
    cyberpi.led.on(r, g, b, id="all")


# ---------------------------------------------------------------- control Bluetooth
def pad_ok():
    return _HAS_PAD


def pad_key(name):
    if not _HAS_PAD:
        return False
    return gamepad.is_key_pressed(name)


def pad_axis(name):
    if not _HAS_PAD:
        return 0
    return gamepad.get_joystick(name)

software/core/settings.py:
# Rover X 2026: menú de ajustes en el CyberPi, calibración de línea y guardado de parámetros.
#
# Desde el menú de inicio: joystick a la DERECHA. Dentro del menú:
#   arriba/abajo  = elegir parámetro o acción
#   izq./derecha  = bajar / subir el valor
#   A             = probar (mueve el brazo o la garra a ese valor, o ejecuta la acción)
#   B             = guardar y salir
# Los valores se guardan en el robot (PARAMS_FILE) y se cargan al encender. Si el CyberPi no
# permite escribir archivos, los cambios duran hasta apagarlo: anótalos en config.py.

import json
import hal
import config as cfg
import motion
import gripper

ACTIONS = ["Calibrar linea", "Ver sensores", "Probar giro 90", "Probar recta 50",
           "Restaurar valores"]
DEFAULTS = {}


def remember_defaults():
    for k in cfg.P:
        DEFAULTS[k] = cfg.P[k]


def snapshot():
    cal = {}
    for pr in cfg.PROBES:
        cal[pr] = [cfg.LINE_CAL[pr][0], cfg.LINE_CAL[pr][1]]
    params = {}
    for k in cfg.P:
        params[k] = cfg.P[k]
    return {"P": params, "LINE_CAL": cal}


def apply(data):
    """Aplica un diccionario guardado; ignora claves desconocidas (versiones viejas)."""
    for k in data.get("P", {}):
        if k in cfg.P:
            cfg.P[k] = data["P"][k]
    cal = data.get("LINE_CAL", {})
    for pr in cal:
        if pr in cfg.LINE_CAL:
            cfg.LINE_CAL[pr] = [cal[pr][0], cal[pr][1]]


def save():
    try:
        f = open(cfg.PARAMS_FILE, "w")
        f.write(json.dumps(snapshot()))
        f.close()
        return True
    except Exception:
        return False


def load():
    try:
        f = open(cfg.PARAMS_FILE)
        data = json.loads(f.read())
        f.close()
        apply(data)
        return True
    except Exception:
        return False


# ---------------------------------------------------------------- calibración de línea
def cal_from_samples(samples):
    """samples: dict sonda -> lista de lecturas de luz. Devuelve dict sonda -> [blanco, negro]
    o None si alguna sonda no vio contraste (no pasó sobre la línea)."""
    out = {}
    for pr in cfg.PROBES:
        s = samples[pr]
        hi = max(s)
        lo = min(s)
        if hi - lo < 15:
            return None
        out[pr] = [hi, lo]
    return out


def calibrate_line():
    """Con el robot centrado sobre la línea: gira ~45° a cada lado leyendo las 4 sondas."""
    hal.show("Calibrando linea...", line=2)
    samples = {}
    for pr in cfg.PROBES:
        samples[pr] = []
    start = hal.heading()
    v = cfg.P["v_turn_min"] * 1.3
    for target, d in ((45, 1), (-45, -1), (0, 1)):
        t0 = hal.now()
        while hal.now() - t0 < 4:
            h = hal.heading() - start
            if (d > 0 and h >= target) or (d < 0 and h <= target):
                break
            hal.drive(d * v, -d * v)
            for pr in cfg.PROBES:
                samples[pr].append(hal.probe_light(pr))
            hal.wait(cfg.LOOP_DT)
    hal.stop()
    cal = cal_from_samples(samples)
    if cal is None:
        hal.show("Sin contraste: centrar", line=2)
        return False
    for pr in cal:
        cfg.LINE_CAL[pr] = cal[pr]
    hal.show("Linea OK", line=2)
    return True


def show_sensors():
    """Muestra oscuridad por sonda, offset y distancia hasta presionar B."""
    hal.wait(0.3)
    while not hal.button("b"):
        dk = hal.darkness()
        hal.show("%.2f %.2f %.2f %.2f" % (dk["L2"], dk["L1"], dk["R1"], dk["R2"]), line=1)
        hal.show("offset %d" % hal.offset_from(dk), line=2)
        hal.show("pitch %d  rumbo %d" % (hal.pitch(), hal.heading()), line=3)
        hal.wait(0.05)
    hal.wait(0.3)


def run_action(name):
    if name == "Calibrar linea":
        return calibrate_line()
    if name == "Ver sensores":
        show_sensors()
        return True
    if name == "Probar giro 90":
        return motion.turn(90)
    if name == "Probar recta 50":
        return motion.straight(50)
    if name == "Restaurar valores":
        for k in DEFAULTS:
            cfg.P[k] = DEFAULTS[k]
        return True
    return False


# ---------------------------------------------------------------- menú
def items():
    out = []
    for t in cfg.TUNE:
        out.append(("param", t))
    for a in ACTIONS:
        out.append(("action", a))
    return out


def bump(spec, direction):
    """Cambia el parámetro spec = (grupo, clave, paso, min, max) un paso en esa dirección."""
    key = spec[1]
    v = cfg.P[key] + direction * spec[2]
    v = hal.clamp(v, spec[3], spec[4])
    if isinstance(spec[2], float):
        v = round(v, 3)
    else:
        v = int(v)
    cfg.P[key] = v
    return v


def try_param(spec):
    """Prueba física de un parámetro: el brazo va a la altura, la garra a la apertura."""
    key = spec[1]
    if key.startswith("h_"):
        gripper.arm_to(cfg.P[key])
    elif key.startswith("claw_"):
        gripper.claw(cfg.P[key])
    elif key.startswith("arm_"):
        gripper.arm_to(cfg.P["h_carry"])


def menu():
    lst = items()
    i = 0
    hal.wait(0.3)
    while True:
        kind, it = lst[i]
        if kind == "param":
            hal.show("%s  %d/%d" % (it[0], i + 1, len(lst)), line=0)
            hal.show("%s = %s" % (it[1], cfg.P[it[1]]), line=1, size=16)
            hal.show("<- -> valor  A prueba", line=2)
        else:
            hal.show("Accion  %d/%d" % (i + 1, len(lst)), line=0)
            hal.show(it, line=1, size=16)
            hal.show("A = ejecutar", line=2)
        hal.show("B = guardar y salir", line=3)
        if hal.button("down"):
            i = (i + 1) % len(lst)
            hal.wait(0.2)
        elif hal.button("up"):
            i = (i - 1) % len(lst)
            hal.wait(0.2)
        elif kind == "param" and hal.button("right"):
            bump(it, 1)
            hal.wait(0.15)
        elif kind == "param" and hal.button("left"):
            bump(it, -1)
            hal.wait(0.15)
        elif hal.button("a"):
            if kind == "param":
                try_param(it)
            else:
                run_action(it)
            hal.wait(0.3)
        elif hal.button("b"):
            ok = save()
            hal.show("Guardado" if ok else "No se pudo guardar", line=3)
            hal.wait(0.8)
            hal.clear_abort()
            return
        hal.wait(0.02)

software/controls/linefollow.py:
# Rover X 2026: seguidor de línea PID con detección de cruces robusta para línea delgada.
#
# Cruces "con memoria": con una línea de 10-30 mm y el robot oscilando, las dos sondas
# exteriores casi nunca ven negro AL MISMO TIEMPO. Por eso un cruce se arma con lo que vean
# L2 y R2 dentro de una ventana de avance (P["cross_win"] cm, medida con encoders):
#   "X" = las dos exteriores vieron negro, "L" = solo la izquierda, "R" = solo la derecha.
# Los giros se escriben en la ruta (missions.py); las marcas verdes son opcionales (P["green"]).

import hal
import config as cfg
import colors
import motion
import geometry as geo

_last_err = 0
_integral = 0
_pending_turn = 0        # marcas verdes: -1 izq, 1 der, 2 media vuelta

# rastreador de cruces
_win_start = None        # odometría absoluta donde una exterior vio negro por primera vez
_seen_l = False
_seen_r = False
_clear_since = None      # odometría desde que ambas exteriores están en blanco (refractario)
_armed = True
last_junction = None     # (tipo, odometría absoluta del inicio del cruce)
last_edge = None         # odometría absoluta al salir de una zona de color (leave_color)
_after_turn = False      # tras girar en un cruce, el siguiente seguimiento empieza desarmado
bias_cm = 0.0            # ir corrido de la línea: + = la línea queda a la DERECHA del robot (cm)


def reset():
    global _last_err, _integral, _pending_turn
    _last_err = 0
    _integral = 0
    _pending_turn = 0
    reset_junctions()


def reset_junctions():
    global _win_start, _seen_l, _seen_r, _clear_since, _armed
    _win_start = None
    _seen_l = False
    _seen_r = False
    _clear_since = None
    _armed = True


def correction(err, last_err, integral):
    """Corrección PID (función pura para poder probarla en PC)."""
    return cfg.P["kp"] * err + cfg.P["ki"] * integral + cfg.P["kd"] * (err - last_err)


def drive_with(err, speed):
    global _last_err, _integral
    if bias_cm:
        po = cfg.P["probe_pitch"] / 2.0 + cfg.P.get("probe_outer", cfg.P["probe_pitch"])
        err -= bias_cm / po * 100.0
    _integral = hal.clamp(_integral + err, -200, 200)
    c = correction(err, _last_err, _integral)
    _last_err = err
    # línea a la izquierda (err < 0) -> frenar la oruga izquierda
    hal.drive(speed + c, speed - c)


def step(speed):
    """Un ciclo de control. Devuelve los bits leídos."""
    err, bits = hal.line_read()
    drive_with(err, speed)
    return bits


def sees_line(bits):
    return bits["L2"] or bits["L1"] or bits["R1"] or bits["R2"]


def track_junction(bits, odo):
    """Actualiza el rastreador con una lectura. Devuelve "X", "L", "R" al cerrar un cruce, o None."""
    global _win_start, _seen_l, _seen_r, _clear_since, _armed, last_junction
    left = bits.get("L2x", bits["L2"])
    right = bits.get("R2x", bits["R2"])
    outer = left or right
    if not _armed:
        # esperar a salir del cruce anterior: 1.5 cm con las exteriores en blanco
        if outer:
            _clear_since = None
        elif _clear_since is None:
            _clear_since = odo
        elif odo - _clear_since >= 1.5:
            _armed = True
        return None
    if outer:
        if _win_start is None:
            _win_start = odo
        _seen_l = _seen_l or left
        _seen_r = _seen_r or right
    if _win_start is None:
        return None
    if (_seen_l and _seen_r) or odo - _win_start >= cfg.P["cross_win"]:
        kind = "X" if (_seen_l and _seen_r) else ("L" if _seen_l else "R")
        last_junction = (kind, _win_start)
        _win_start = None
        _seen_l = False
        _seen_r = False
        _armed = False
        _clear_since = None
        return kind
    return None


def _check_green():
    global _pending_turn
    left = colors.read("L2") == "green"
    right = colors.read("R2") == "green"
    if left and right:
        _pending_turn = 2
    elif left:
        _pending_turn = -1
    elif right:
        _pending_turn = 1


def turn_at_junction(deg):
    """Avanza hasta que el CENTRO DE GIRO quede sobre el último cruce, gira y se alinea."""
    done = 0
    if last_junction is not None:
        done = hal.odo_abs() - last_junction[1]
    adv = geo.turn_advance() - done
    if abs(adv) > 0.5:
        motion.straight(adv, cfg.P["v_slow"])
    if deg == 0:
        return True
    motion.turn(deg * 0.85)                    # el último tramo lo termina spin_to_line
    ok = motion.spin_to_line(1 if deg > 0 else -1, timeout=2.0, leave=False)
    reset()
    # el otro brazo del cruce sigue bajo las sondas: no contarlo como un cruce nuevo
    global _after_turn
    _after_turn = True
    return ok


def follow_until(cond, speed=None, timeout=10.0, green=False):
    """Sigue la línea hasta que cond(bits, junction) sea verdadero.

    junction es "X"/"L"/"R" en el ciclo en que se cierra un cruce, si no None.
    Si la línea se pierde más de P["lost_s"] segundos, devuelve False."""
    global _pending_turn, _after_turn, _armed
    if speed is None:
        speed = cfg.P["v_line"]
    reset()
    if _after_turn:
        _after_turn = False
        _armed = False          # se arma tras 1.5 cm con las exteriores en blanco
    t0 = hal.now()
    lost_since = None
    while hal.now() - t0 < timeout:
        if hal.abort_requested():
            break
        err, bits = hal.line_read()
        j = track_junction(bits, hal.odo_abs())
        if cond(bits, j):
            hal.stop()
            return True
        if green and cfg.P["green"] == 1:
            if _pending_turn == 0:
                _check_green()
            elif j is not None:
                t = _pending_turn
                _pending_turn = 0
                turn_at_junction(180 if t == 2 else 90 * t)
                continue
        if sees_line(bits):
            lost_since = None
        elif lost_since is None:
            lost_since = hal.now()
        elif hal.now() - lost_since > cfg.P["lost_s"]:
            break
        drive_with(err, speed)
        hal.wait(cfg.LOOP_DT)
    hal.stop()
    return False


# ---------------------------------------------------------------- condiciones de parada
def at_junction(count=1, kind="any"):
    """Cuenta cruces; kind = "any", "X", "L" o "R" ("L" también cuenta las "X")."""
    state = {"n": 0}

    def cond(bits, j):
        if j is not None and (kind == "any" or j == kind or j == "X"):
            state["n"] += 1
        return state["n"] >= count
    return cond


def at_color(name, probes=("L1", "R1")):
    def cond(bits, j):
        for pr in probes:
            if colors.read(pr) == name:
                return True
        return False
    return cond


def color_then_cm(name, cm, probes=None):
    """Verdadero `cm` después de que alguna sonda vio ese color. Sirve para terminar arriba de una
    rampa SIN detenerse sobre la pendiente (parado ahí, el robot se resbalaba hacia atrás al
    arrancar; lo mostró el simulador con una rampa de 40°)."""
    if probes is None:
        probes = cfg.PROBES
    state = {"from": None}

    def cond(bits, j):
        if state["from"] is None:
            for pr in probes:
                if colors.read(pr) == name:
                    state["from"] = hal.odo_abs()
                    break
            return False
        return hal.odo_abs() - state["from"] >= cm
    return cond


def after_cm(cm):
    start = hal.odo_abs()

    def cond(bits, j):
        return hal.odo_abs() - start >= cm
    return cond


def leave_color(name, probes=None):
    """Verdadero cuando las sondas, después de haber visto la zona de ese color, la dejan de ver
    (3 lecturas seguidas).
    Guarda la odometría en last_edge: es la referencia para medir desde el borde de la zona."""
    if probes is None:
        probes = cfg.PROBES     # la línea cruza la zona: las centrales leen negro
    state = {"n": 0, "seen": False}

    def cond(bits, j):
        global last_edge
        inside = False
        for pr in probes:
            if colors.read(pr) == name:
                inside = True
        if inside:
            state["seen"] = True
        if not state["seen"]:          # primero hay que entrar a la zona (p. ej. al subir una rampa)
            return False
        state["n"] = 0 if inside else state["n"] + 1
        if state["n"] >= cfg.COLOR_CONFIRM:
            last_edge = hal.odo_abs()
            return True
        return False
    return cond


def obstacle_within(cm):
    """Solo con ultrasónico (HAS_US = True)."""
    def cond(bits, j):
        d = hal.distance_cm()
        return 0 < d <= cm
    return cond


def line_end(cm=2.0):
    """Verdadero cuando ninguna sonda ve línea durante `cm` de avance (en una curva cerrada la
    línea se pierde un instante y no es el final; lo mostró el simulador)."""
    state = {"since": None}

    def cond(bits, j):
        if sees_line(bits):
            state["since"] = None
            return False
        odo = hal.odo_abs()
        if state["since"] is None:
            state["since"] = odo
        return odo - state["since"] >= cm
    return cond


def pitch_above(deg):
    def cond(bits, j):
        return hal.pitch() >= deg
    return cond

software/controls/motion.py:
# Rover X 2026: movimientos con giroscopio y encoders (sin línea).
#
# Todas las funciones devuelven True si terminaron bien y False si se acabó el tiempo
# o se pidió abortar (botón B del CyberPi).

import hal
import config as cfg
import geometry as geo
import colors


def sign(v):
    if v < 0:
        return -1
    return 1


def turn(deg, timeout=None):
    """Giro relativo en el lugar; positivo = derecha."""
    if timeout is None:
        timeout = cfg.TURN_TIMEOUT_S
    target = hal.heading() + deg
    t0 = hal.now()
    settled = None
    while hal.now() - t0 < timeout:
        if hal.abort_requested():
            break
        err = target - hal.heading()
        if abs(err) <= cfg.P["turn_tol"]:
            hal.stop()
            if settled is None:
                settled = hal.now()
            elif hal.now() - settled >= cfg.TURN_SETTLE_S:
                return True
        else:
            settled = None
            p = cfg.P["turn_kp"] * err
            p = sign(p) * hal.clamp(abs(p), cfg.P["v_turn_min"], cfg.P["v_turn_max"])
            hal.drive(p, -p)
        hal.wait(cfg.LOOP_DT)
    hal.stop()
    return False


def pivot(deg, speed=None, timeout=None):
    """Giro relativo sobre UNA oruga (la otra detenida); positivo = derecha. Avanza la oruga de
    afuera: la de la derecha queda quieta al girar a la derecha. Si la oruga que se mueve patina
    (recortes del pasillo) el robot solo gira más lento: el centro del giro es la oruga quieta y
    la posición final depende solo del ángulo (en un giro en el lugar una oruga que patina corre
    el robot hasta 6 cm sin que la odometría lo vea). speed < 0 = pivote hacia atrás."""
    if timeout is None:
        timeout = cfg.TURN_TIMEOUT_S * 2
    if speed is None:
        speed = cfg.P["v_turn_max"]
    target = hal.heading() + deg
    t0 = hal.now()
    settled = None
    while hal.now() - t0 < timeout:
        if hal.abort_requested():
            break
        err = target - hal.heading()
        if abs(err) <= cfg.P["turn_tol"]:
            hal.stop()
            if settled is None:
                settled = hal.now()
            elif hal.now() - settled >= cfg.TURN_SETTLE_S:
                return True
        else:
            settled = None
            p = hal.clamp(abs(cfg.P["turn_kp"] * err) * 2, cfg.P["v_turn_min"] * 1.5, abs(speed))
            # el giro sale de la diferencia izquierda - derecha (> 0 = a la derecha):
            # a la derecha hacia adelante mueve la izquierda, hacia atrás la derecha
            fwd = speed > 0
            if err > 0:
                hal.drive(p, 0) if fwd else hal.drive(0, -p)
            else:
                hal.drive(0, p) if fwd else hal.drive(-p, 0)
        hal.wait(cfg.LOOP_DT)
    hal.stop()
    return False


def wrap180(deg):
    while deg > 180:
        deg -= 360
    while deg < -180:
        deg += 360
    return deg


def turn_to(heading, timeout=None):
    """Gira hasta un rumbo absoluto por el camino más corto (antes podía dar la vuelta larga)."""
    return turn(wrap180(heading - hal.heading()), timeout)


def _hold(speed, target):
    # el giro sale de la DIFERENCIA entre orugas (izquierda > derecha = a la derecha), igual
    # hacia adelante que hacia atrás. Antes se invertía la corrección al retroceder y el rumbo se
    # iba en vez de corregirse (en un retroceso largo sobre un recorte el robot daba vueltas).
    corr = cfg.P["head_kp"] * (target - hal.heading())
    hal.drive(speed + corr, speed - corr)


def straight_until(cond, speed=None, timeout=5.0, target=None):
    """Avanza recto (manteniendo el rumbo) hasta que cond() sea verdadero."""
    if speed is None:
        speed = cfg.P["v_straight"]
    if target is None:
        target = hal.heading()
    t0 = hal.now()
    while hal.now() - t0 < timeout:
        if hal.abort_requested():
            break
        if cond():
            hal.stop()
            return True
        _hold(speed, target)
        hal.wait(cfg.LOOP_DT)
    hal.stop()
    return False


def straight(cm, speed=None, timeout=None, target=None):
    """Avanza (cm > 0) o retrocede (cm < 0) una distancia medida con encoders.

    target: rumbo (hal.heading) que se sostiene con el giroscopio. Sin target se sostiene el
    rumbo con el que empezó; con target, el error del giro anterior y los golpes del piso se
    corrigen durante el avance."""
    if speed is None:
        speed = cfg.P["v_straight"]
    speed = abs(speed) * sign(cm)
    if timeout is None:
        timeout = 1.0 + abs(cm) / 8.0
    hal.reset_odometer()
    goal = abs(cm)
    return straight_until(lambda: abs(hal.odometer_cm()) >= goal, speed, timeout, target)


def climb(speed=None, timeout=None, extra_cm=None):
    """Sube una rampa o escalera: espera a inclinarse, luego a quedar plano, y avanza
    extra_cm para quedar completamente dentro del nivel."""
    if speed is None:
        speed = cfg.P["v_ramp"]
    if timeout is None:
        timeout = cfg.RAMP_TIMEOUT_S
    if extra_cm is None:
        extra_cm = geo.ramp_extra()
    target = hal.heading()
    t0 = hal.now()
    climbing = False
    flat_since = None
    while hal.now() - t0 < timeout:
        if hal.abort_requested():
            hal.stop()
            return False
        p = hal.pitch()
        if not climbing:
            if p >= cfg.P["pitch_ramp"]:
                climbing = True
        elif p <= cfg.P["pitch_flat"]:
            if flat_since is None:
                flat_since = hal.now()
            elif hal.now() - flat_since >= cfg.FLAT_CONFIRM_S:
                hal.stop()
                return straight(extra_cm, cfg.P["v_straight"])
        else:
            flat_since = None
        _hold(speed, target)
        hal.wait(cfg.LOOP_DT)
    hal.stop()
    return False


def stairs(extra_cm=None):
    return climb(cfg.P["v_stairs"], cfg.STAIRS_TIMEOUT_S, extra_cm)


def sees_color(name):
    """Alguna de las cuatro sondas ve ese color. La línea pasa por encima de las zonas, así que
    las centrales leen negro; las exteriores van a los lados (lo mostró el simulador)."""
    for pr in cfg.PROBES:
        if colors.read(pr) == name:
            return True
    return False


def climb_crest(after_cm, speed=None, timeout=None, target=None, color=None, arm_h=None):
    """Sube hasta pasar la cima (el pitch ya subió y empieza a bajar: el frente está arriba) y
    avanza after_cm medidos con encoder. Sirve cuando arriba no hay espacio para esperar a quedar
    plano (nivel 4: la torre está a ~20 cm de la escalera; lo mostró el simulador)."""
    if speed is None:
        speed = cfg.P["v_stairs"]
    if timeout is None:
        timeout = cfg.STAIRS_TIMEOUT_S
    if target is None:
        target = hal.heading()
    t0 = hal.now()
    top = 0                         # pitch máximo visto
    while hal.now() - t0 < timeout:
        if hal.abort_requested():
            hal.stop()
            return False
        p = hal.pitch()
        if p > top:
            top = p
        # cima: ya subió y el pitch bajó CREST_DROP grados desde su máximo (el frente está arriba;
        # esperar a quedar plano no sirve porque la cola sigue en la escalera)
        if color is not None:
            # referencia exacta: las sondas centrales ven el color de la zona de arriba
            if top >= cfg.P["pitch_ramp"] and sees_color(color):
                if arm_h is not None:      # el brazo se mueve mientras sigue avanzando (sin parar)
                    hal.servo(cfg.SERVO_ARM, geo.arm_servo(arm_h))
                return straight(after_cm, cfg.P["v_ramp"], target=target)
        elif top >= cfg.P["pitch_ramp"] and p <= top - cfg.CREST_DROP:
            return straight(after_cm, cfg.P["v_ramp"], target=target)   # aún en pendiente: con fuerza
        _hold(speed, target)
        hal.wait(cfg.LOOP_DT)
    hal.stop()
    return False


def spin_to_line(direction=1, timeout=3.0, leave=True):
    """Gira en el lugar (1 = derecha, -1 = izquierda) hasta que las sondas centrales vean línea.

    leave=True: si ya está sobre una línea, primero sale de ella (para buscar OTRA línea).
    leave=False: si ya ve la línea, termina (después de un giro en un cruce las sondas, que van
    cerca del centro de giro, ya quedan sobre la línea nueva)."""
    t0 = hal.now()
    # salir primero de la línea actual si ya estamos encima
    while leave and hal.now() - t0 < timeout * 0.3:
        b = hal.line_bits()
        if not (b["L1"] or b["R1"]):
            break
        hal.drive(direction * cfg.P["v_turn_min"] * 1.5, -direction * cfg.P["v_turn_min"] * 1.5)
        hal.wait(cfg.LOOP_DT)
    while hal.now() - t0 < timeout:
        if hal.abort_requested():
            break
        b = hal.line_bits()
        if b["L1"] or b["R1"]:
            hal.stop()
            return True
        hal.drive(direction * cfg.P["v_turn_min"] * 1.5, -direction * cfg.P["v_turn_min"] * 1.5)
        hal.wait(cfg.LOOP_DT)
    hal.stop()
    return False


def on_line():
    b = hal.line_bits()
    return b["L1"] or b["R1"]


def seek_line(speed=None, max_cm=60, target=None):
    """Avanza recto (con giroscopio) hasta que las sondas centrales vean una línea."""
    if speed is None:
        speed = cfg.P["v_slow"]
    hal.reset_odometer()
    t = 1.0 + max_cm / 8.0

    found = [False]

    def cond():
        if on_line():
            found[0] = True         # la lectura que detuvo el avance (releerla con ruido fallaba)
            return True
        return abs(hal.odometer_cm()) >= max_cm
    straight_until(cond, speed, t, target)
    return found[0]


def drive_to_edge(color, speed=None, max_cm=30, target=None):
    """Avanza recto (IMU) hasta SALIR de una zona de color: referencia fija para empezar una
    maniobra sin importar dónde quedó o se colocó el robot dentro de la zona."""
    if speed is None:
        speed = cfg.P["v_slow"]
    hal.reset_odometer()
    state = {"seen": False, "out": 0, "ok": False}

    def cond():
        inside = sees_color(color)
        if inside:
            state["seen"] = True
            state["out"] = 0
        elif state["seen"]:
            state["out"] += 1
            if state["out"] >= cfg.COLOR_CONFIRM:
                state["ok"] = True
                return True
        return abs(hal.odometer_cm()) >= max_cm
    straight_until(cond, speed, 1.0 + max_cm / 6.0, target)
    return state["ok"]


def drive_to_cross(speed=None, max_cm=15, target=None):
    """Avanza recto (IMU) hasta que las DOS sondas exteriores ven negro fuerte: una línea que
    cruza el camino. No es seguir la línea: solo sirve de referencia para corregir la distancia.
    Las marcas verdes y el tope no cuentan (cross_th). Devuelve True si encontró el cruce."""
    if speed is None:
        speed = cfg.P["v_slow"]
    hal.reset_odometer()
    st = {"found": False, "l": None, "r": None}

    def cond():
        _, bits = hal.line_read()
        odo = hal.odometer_cm()
        # con memoria (como los cruces): cada exterior puede ver la línea en distinto momento
        # si la línea no es perpendicular al camino (antes se pedían las dos a la vez)
        if bits.get("L2x", bits["L2"]):
            st["l"] = odo
        if bits.get("R2x", bits["R2"]):
            st["r"] = odo
        if st["l"] is not None and st["r"] is not None and abs(st["l"] - st["r"]) <= cfg.P["cross_win"]:
            st["found"] = True
            return True
        return abs(odo) >= max_cm
    straight_until(cond, speed, 1.0 + max_cm / 6.0, target)
    return st["found"]


def detour(side=None):
    """Rodea un obstáculo fijo (torre, misión 10) y vuelve a buscar la línea.
    side: -1 = por la izquierda, 1 = por la derecha. Distancias desde geometry.py."""
    if side is None:
        side = -1
    start = hal.heading()
    ok = turn(90 * side)
    ok = ok and straight(geo.detour_out())
    ok = ok and turn_to(start)
    ok = ok and straight(geo.detour_pass())
    ok = ok and turn(-90 * side)
    if not ok:
        return False
    if not straight_until(on_line, cfg.P["v_slow"], timeout=4.0):
        return False
    straight(geo.turn_advance(), cfg.P["v_slow"])   # centro de giro sobre la línea
    # quedó perpendicular a la línea; para seguir en el rumbo original se gira hacia el mismo
    # lado del rodeo (antes giraba al revés y regresaba hacia el obstáculo: lo mostró el simulador)
    return spin_to_line(side, leave=False)

software/autonomous/autonomous.py:
# Rover X 2026: ejecutor del área automática.
#
# Ejecuta las misiones de missions.py desde el nivel de inicio elegido, muestra el avance
# en la pantalla del CyberPi y se detiene si se acaba el tiempo, si falla una misión
# crítica o si se presiona A (cfg.ABORT_BUTTON: parar para pedir reinicio).

import hal
import config as cfg
import geometry as geo
import colors
import motion
import linefollow as lf
import gripper
import missions as ms
import odometry as odo

cards = []               # [(color, odometría absoluta al detectarla)]
results = []             # [(id, ok)]
last_advance = 0         # cm del último acercamiento (para regresar lo mismo con "retreat")
heading_ref = 0          # rumbo de mapa = hal.heading() + heading_ref (paso "ref")
goal_entry = None        # odometría al entrar a la zona de la meta (lectura de tarjetas)
run_level = 1            # nivel en el que arrancó el autónomo (o el del último reinicio)
current_level = 1        # nivel de la misión en curso
pass_skipped = set()     # misiones saltadas en la pasada actual (ya hechas antes de un reinicio)
pass_ran = set()         # misiones corridas en la pasada actual
placed = True            # el robot recién fue colocado a mano (arranque o reinicio)
next_level = 1           # nivel que conviene elegir después del tramo
completed = set()        # misiones logradas en este encendido (se saltan al repetir un tramo)


def reset_state():
    """Todo lo que una corrida anterior pudo dejar (al relanzar el autónomo desde el menú sin
    apagar el robot, una referencia vieja movía el primer giro; lo mostró el simulador)."""
    global cards, results, last_advance, heading_ref, goal_entry
    goal_entry = None
    cards = []
    results = []
    last_advance = 0
    heading_ref = 0
    lf.reset()
    lf.last_junction = None
    lf.last_edge = None
    lf._after_turn = False


def val(x):
    """Número tal cual, o el valor actual del parámetro cfg.P con ese nombre."""
    if isinstance(x, str):
        return cfg.P[x]
    return x


# ---------------------------------------------------------------- condiciones de línea
def make_cond(spec):
    kind = spec[0]
    if kind == "junction":
        return lf.at_junction(spec[1], spec[2])
    if kind == "color":
        # las marcas de color van JUNTO a la línea: se revisan las cuatro sondas
        return lf.at_color(spec[1], cfg.PROBES)
    if kind == "color_cm":
        return lf.color_then_cm(spec[1], val(spec[2]))
    if kind == "cm":
        return lf.after_cm(val(spec[1]))
    if kind == "leave":
        return lf.leave_color(spec[1])
    if kind == "obstacle":
        return lf.obstacle_within(val(spec[1]))       # solo con ultrasónico
    if kind == "end":
        return lf.line_end()
    if kind == "pitch":
        return lf.pitch_above(cfg.P["pitch_ramp"])
    if kind == "head":
        # ("head", rumbo de mapa, tolerancia): en una curva de la línea, parar al pasar por ese
        # rumbo (p. ej. a media curva, antes de que el seguidor se abra hacia un muro)
        target, tol = spec[1], spec[2]
        return lambda bits, j: abs(motion.wrap180(target - heading_ref - hal.heading())) < tol
    raise ValueError("condicion desconocida: %s" % kind)


# ---------------------------------------------------------------- misiones 11 y 12
def red_index(found):
    """Posición (0..5) de la tarjeta roja, o -1."""
    for i in range(len(found)):
        if found[i][0] == "red":
            return i
    return -1


def _note_card(c, odo):
    """Registra la tarjeta si no es una ya vista (mismo color a menos de 6 cm: la tarjeta mide
    4.7 cm y al retroceder y volver a pasar se lee en sus dos orillas)."""
    for c0, o0 in cards:
        if c0 == c and abs(o0 - odo) < 6:
            return False
    cards.append((c, odo))
    colors.show(c)
    return True


def _scan_back(back_cm):
    """Retrocede recto (rumbo con el giroscopio) leyendo tarjetas: al volver a la línea
    después de rodear la torre, la sonda ya pasó la primera tarjeta."""
    start = hal.odo_abs()
    h0 = hal.heading()
    t0 = hal.now()
    last, same = "white", 0
    v = cfg.P["v_slow"]
    while start - hal.odo_abs() < back_cm and hal.now() - t0 < 4:
        if hal.abort_requested():
            break
        c = colors.read(cfg.CARD_PROBE)
        if c == last:
            same += 1
        else:
            last, same = c, 1
        if same == cfg.COLOR_CONFIRM and colors.is_card_color(c):
            _note_card(c, hal.odo_abs())
        corr = hal.clamp(cfg.P["head_kp"] * (h0 - hal.heading()), -15, 15)
        hal.drive(-v + corr, -v - corr)
        hal.wait(cfg.LOOP_DT)
    hal.stop()


def scan_cards(back_cm=0):
    """Sigue la línea despacio y registra cada tarjeta de color (color + odometría).
    back_cm: antes, retrocede eso leyendo (tarjetas que quedaron detrás de la sonda)."""
    global cards
    cards = []
    if back_cm > 0:
        _scan_back(back_cm)
    lf.reset()
    start = hal.odo_abs()
    t0 = hal.now()
    last = "white"
    same = 0
    goal_from = None
    while hal.now() - t0 < 15 and hal.odo_abs() - start < cfg.CARD_SCAN_MAX_CM:
        # la X azul de la meta: azul por más de GOAL_RUN_CM seguidos (una tarjeta mide ~4.7 cm).
        # Sin esto seguía de largo y se salía de la arena (lo mostró el simulador).
        if motion.sees_color(cfg.GOAL_COLOR):
            if goal_from is None:
                goal_from = hal.odo_abs()
            elif hal.odo_abs() - goal_from >= cfg.GOAL_RUN_CM:
                global goal_entry
                goal_entry = goal_from
                break
        else:
            goal_from = None
        if hal.abort_requested():
            break
        c = colors.read(cfg.CARD_PROBE)
        if c == last:
            same += 1
        else:
            last = c
            same = 1
        odo = hal.odo_abs()
        if same == cfg.COLOR_CONFIRM and colors.is_card_color(c):
            # no se para al contar CARD_COUNT: la última tarjeta (azul) está junto a la meta azul
            # y parar encima de ella hacía que stop_in la tomara por la meta
            _note_card(c, odo)
        lf.step(cfg.P["v_slow"])
        hal.wait(cfg.LOOP_DT)
    hal.stop()
    if goal_entry is not None and goal_entry >= start:   # meta confirmada en esta lectura:
        cards = [k for k in cards if k[1] < goal_entry - 1]  # su azul no es una tarjeta
    cards.sort(key=lambda k: k[1])          # en orden a lo largo de la línea (odometría)
    return len(cards) > 0


def drop_red():
    i = red_index(cards)
    if i < 0:
        return False
    side = cfg.P["bar_side"]
    ok = motion.straight(geo.card_to_center(cards[i][1], hal.odo_abs()), cfg.P["v_slow"])
    ok = ok and motion.turn(90 * side)
    gripper.arm_to(cfg.P["h_bar"])
    ok = ok and motion.straight(cfg.P["bar_reach"], cfg.P["v_slow"])
    gripper.open_claw()
    motion.straight(-cfg.P["bar_reach"], cfg.P["v_slow"])
    gripper.arm_to(cfg.P["h_carry"])
    motion.turn(-90 * side)
    motion.spin_to_line(-side, timeout=1.5)
    return ok


def stop_in(color):
    """Para completamente dentro de la zona: avanza zone_extra() contado desde que las sondas
    ENTRARON a la zona (si la lectura de tarjetas ya entró, no se vuelve a contar desde aquí;
    antes el robot se pasaba y salía por el otro lado: lo mostró el simulador)."""
    global goal_entry
    if goal_entry is None:
        start = {"odo": None}

        def cond(bits, j):
            if motion.sees_color(color):
                start["odo"] = hal.odo_abs()
                return True
            return False
        if not lf.follow_until(cond, cfg.P["v_line"], 15):
            return False
        goal_entry = start["odo"]
    rest = geo.zone_extra() - (hal.odo_abs() - goal_entry)
    if rest > 0.5:
        motion.straight(rest, cfg.P["v_slow"])
    hal.stop()
    return True


def _advance(cm):
    global last_advance
    last_advance = cm
    return motion.straight(cm, cfg.P["v_slow"])


def approach_pedestal(h, from_cross):
    """Garra sobre el centro de un pedestal que está a from_cross cm del último cruce."""
    traveled = 0
    if lf.last_junction is not None:
        traveled = hal.odo_abs() - lf.last_junction[1]
    return _advance(geo.pedestal_advance(val(h), val(from_cross), traveled))


def approach_object(h, dist):
    """Garra sobre un objeto cuyo centro está a dist cm del centro de giro, al frente."""
    return _advance(geo.reach_advance(val(dist), val(h)))


def to_tower():
    """Sigue la línea hasta quedar a side_margin de la torre (referencia: borde de la zona verde)."""
    traveled = 0
    if lf.last_edge is not None:
        traveled = hal.odo_abs() - lf.last_edge
    adv = geo.tower_advance(traveled)
    if adv < 0:                         # ya está más cerca de lo debido: retroceder recto
        return motion.straight(adv, cfg.P["v_slow"])
    if adv < 0.5:
        return True
    return lf.follow_until(lf.after_cm(adv), cfg.P["v_slow"], 8)


RAMP_FLAT_DEG = 6.0     # al pie, en plano: corregir el desvío lateral antes de subir
RAMP_MAX_DEG = 1.5      # en la rampa angosta solo sostener: torcerse 3° saca una esquina 0.5 cm


def map_target(deg):
    """Rumbo de mapa -> valor de hal.heading() al que hay que llegar por el camino corto.
    hal.heading() acumula vueltas; sin normalizar, una recta podía "sostener" un rumbo a 360°
    del real y torcerse (lo mostró el simulador)."""
    now = hal.heading()
    return now + motion.wrap180(deg - heading_ref - now)


# ---------------------------------------------------------------- pasos
def run_step(step):
    global heading_ref
    kind = step[0]
    if kind == "line":
        green = len(step) > 4 and step[4]
        return lf.follow_until(make_cond(step[1]), val(step[2]), step[3], green)
    if kind == "jturn":
        return lf.turn_at_junction(step[1])
    if kind == "straight":
        speed = val(step[2]) if len(step) > 2 else cfg.P["v_straight"]
        return motion.straight(val(step[1]), speed)
    if kind == "center":
        return motion.straight(geo.turn_advance(), cfg.P["v_slow"])
    if kind == "turn":
        return motion.turn(step[1])
    if kind == "ref":
        # "ahora miro hacia step[1] grados de mapa" (0 = este, 90 = sur; positivo = horario).
        # Se usa en una recta conocida para que los giros "head" no arrastren el error de rumbo.
        # ("ref", rumbo, nivel): solo si el autónomo ARRANCÓ en ese nivel (robot colocado a mano
        # en la zona de inicio con ese rumbo).
        if len(step) > 2 and step[2] != run_level:
            return True
        heading_ref = step[1] - hal.heading()
        return True
    if kind == "head":
        return motion.turn_to(map_target(step[1]))
    if kind == "drive":
        # ("drive", rumbo, cm[, vel]): girar al rumbo de mapa y avanzar SOSTENIENDO ese rumbo
        # con el IMU (zona de obstáculos: no se arrastra el error del giro)
        target = map_target(step[1])
        speed = val(step[3]) if len(step) > 3 else cfg.P["v_slow"]
        motion.turn_to(target)
        return motion.straight(val(step[2]), speed, target=target)
    if kind == "pose":
        # ("pose", x, y, rumbo): posición conocida en el mapa (cm; x este, y sur) -> odometría
        # rumbo None: el que ya trae ("ref" anterior + giroscopio), solo se fija la posición
        # x o y None: se queda la que trae la odometría (p. ej. solo actualizar el rumbo tras line_ref)
        hdg = step[3] if step[3] is not None else heading_ref + hal.heading()
        ox, oy, _ = odo.pose()
        odo.set_pose(ox if step[1] is None else step[1], oy if step[2] is None else step[2], hdg)
        heading_ref = hdg - hal.heading()
        return True
    if kind == "square":
        # ("square", rumbo, segundos, coord, valor[, vel]): avanzar despacio DURANTE ese tiempo
        # hasta apoyar las orugas en un muro (rumbo perpendicular a él) y fijar esa coordenada de
        # la odometría ("x" o "y") y el rumbo. Por tiempo y no por distancia: con patinaje los
        # encoders cuentan de más y el robot se quedaba antes del muro (lo mostró el simulador).
        # 7o elemento opcional: valor de la OTRA coordenada de la recta a seguir (si no, la actual)
        speed = val(step[5]) if len(step) > 5 and step[5] is not None else cfg.P["v_slow"]
        motion.turn_to(map_target(step[1]))
        x, y, _ = odo.pose()
        if len(step) > 6:
            if step[3] == "x":
                y = step[6]
            else:
                x = step[6]
        odo.track(x, y, step[1], speed, timeout=val(step[2]))   # sostiene rumbo y línea recta
        # parar AQUÍ y esperar: si el paso siguiente empieza con los motores todavía empujando,
        # el robot sigue apretado contra el muro mientras ya gira
        hal.stop()
        hal.wait(0.3)
        x, y, _ = odo.pose()
        if step[3] == "x":
            x = step[4]
        else:
            y = step[4]
        odo.set_pose(x, y, step[1])
        heading_ref = step[1] - hal.heading()
        return True
    if kind == "track_line":
        # ("track_line", rumbo, coord, valor, max_cm[, vel[, max_deg]]): seguir la recta del mapa coord=valor
        # (p. ej. "y", 18.0 con rumbo 0 = hacia el este a esa altura) hasta que las sondas
        # centrales vean una línea. Absorbe el error a lo largo y corrige el lateral.
        speed = val(step[5]) if len(step) > 5 else cfg.P["v_slow"]
        motion.turn_to(map_target(step[1]))
        x, y, _ = odo.pose()
        if step[2] == "x":
            x = step[3]
        else:
            y = step[3]
        return odo.track(x, y, step[1], speed, timeout=2.0 + val(step[4]) / 5.0,
                         max_cm=val(step[4]), stop=motion.on_line,
                         max_deg=step[6] if len(step) > 6 else None)
    if kind == "diag":
        # ("diag", x0, y0, rumbo, max_cm, x_det, y_det[, vel[, head_kp]]): seguir la recta que pasa
        # por (x0, y0) con ese rumbo (cualquiera, no solo este/sur) corrigiendo rumbo y desvío
        # lateral, hasta que CUALQUIER sonda vea una línea. Ese punto de la línea es fijo (la
        # recta no cambia), así que ahí la odometría pasa a (x_det, y_det): el patinaje sobre los
        # recortes solo cambia CUÁNDO llega, no dónde.
        speed = val(step[7]) if len(step) > 7 else cfg.P["v_slow"]

        def seen():
            b = hal.line_bits()
            return any(b[pr] for pr in cfg.PROBES)
        kp0 = cfg.P["head_kp"]
        if len(step) > 8:
            cfg.P["head_kp"] = val(step[8])    # más firme: una oruga sobre un recorte la frena
        try:
            ok = odo.track(step[1], step[2], step[3], speed, timeout=2.0 + val(step[4]) / 4.0,
                           max_cm=val(step[4]), stop=seen)
        finally:
            cfg.P["head_kp"] = kp0
        if ok:
            _, _, h = odo.pose()
            odo.set_pose(step[5], step[6], h)
        return ok
    if kind == "track":
        # ("track", rumbo, coord, valor, cm[, vel]): como track_line pero sin parar en líneas
        speed = val(step[5]) if len(step) > 5 else cfg.P["v_slow"]
        motion.turn_to(map_target(step[1]))
        x, y, _ = odo.pose()
        if step[2] == "x":
            x = step[3]
        else:
            y = step[3]
        odo.track(x, y, step[1], speed, timeout=2.0 + val(step[4]) / 4.0, max_cm=val(step[4]))
        return True
    if kind == "back_to":
        # ("back_to", coord, valor[, vel[, rumbo, otra]]): retroceder hasta que la odometría
        # (encoders + giroscopio, corrige el patinaje de una oruga) llegue a esa coordenada. Con
        # rumbo y otra: por la recta del mapa otra (la otra coordenada) mirando a ese rumbo,
        # corrigiendo el desvío lateral (al retroceder sobre recortes el robot se corría 4 cm)
        speed = val(step[3]) if len(step) > 3 and step[3] is not None else cfg.P["v_slow"]
        i = 0 if step[1] == "x" else 1
        start = odo.pose()[i]
        goal = step[2]
        up = goal > start

        def there():
            v = odo.pose()[i]
            return v >= goal if up else v <= goal
        tmo = 2.0 + abs(goal - start) / 4.0
        if len(step) > 5:
            x, y, _ = odo.pose()
            if step[1] == "x":
                y = step[5]
            else:
                x = step[5]
            return odo.track(x, y, step[4], -abs(speed), timeout=tmo, stop=there)
        return motion.straight_until(there, -abs(speed), timeout=tmo)
    if kind == "ramp_up":
        # ("ramp_up", rumbo, x, color, extra_cm, vel, max_cm): subir una rampa angosta por la recta
        # del mapa x (giroscopio + odometría, sin seguir la línea: el seguidor oscilaba ±4.5° y una
        # oruga salía por la orilla) hasta ver ese color y luego extra_cm más, SIN detenerse
        hdg, x0, color, extra, speed, max_cm = step[1:7]
        speed = val(speed)
        _, y, _ = odo.pose()
        # en plano (antes de inclinarse) todavía se puede corregir el desvío lateral
        odo.track(x0, y, hdg, speed, timeout=4.0, max_cm=12, max_deg=RAMP_FLAT_DEG, halt=False,
                  stop=lambda: abs(hal.pitch()) > 4)
        _, y, _ = odo.pose()
        seen = odo.track(x0, y, hdg, speed, timeout=4.0 + val(max_cm) / 3.0, max_cm=val(max_cm),
                         stop=lambda: motion.sees_color(color), halt=False, max_deg=RAMP_MAX_DEG)
        if not seen:
            hal.stop()
            return False
        _, y, _ = odo.pose()
        odo.track(x0, y, hdg, speed, timeout=2.0 + val(extra) / 3.0, max_cm=val(extra),
                  max_deg=RAMP_MAX_DEG)
        return True
    if kind == "fix_line":
        # ("fix_line", coord, valor, signo): parado sobre una línea recta que está en coord=valor,
        # la desviación medida por las sondas da esa coordenada exacta. signo +1 si la izquierda
        # del robot es hacia +coord (p. ej. mirando al sur y la línea en x)
        po = cfg.P["probe_pitch"] / 2.0 + cfg.P.get("probe_outer", cfg.P["probe_pitch"])
        acc = 0.0
        n = 0
        for _ in range(5):
            err, bits = hal.line_read()
            if bits["L1"] or bits["R1"]:
                acc += err
                n += 1
            hal.wait(cfg.LOOP_DT)
        if n < 3:
            return True                       # no la ve: se queda la odometría
        err_cm = acc / n * po / 100.0         # err < 0: línea a la izquierda
        x, y, h = odo.pose()
        v = step[2] + step[3] * err_cm
        if step[1] == "x":
            x = v
        else:
            y = v
        odo.set_pose(x, y, h)
        return True
    if kind == "bias":
        # ("bias", cm): seguir la línea corrido; + = la línea a la derecha del robot. Para
        # centrar el robot en una rampa cuya línea no va al centro
        lf.bias_cm = step[1]
        return True
    if kind == "fix":
        # ("fix", coord, valor): la odometría está en esa coordenada (p. ej. al ver una línea
        # conocida); el resto de la pose se queda
        x, y, h = odo.pose()
        if step[1] == "x":
            x = step[2]
        else:
            y = step[2]
        odo.set_pose(x, y, h)
        return True
    if kind == "pivot":
        # ("pivot", rumbo[, "back"]): girar al rumbo de mapa sobre UNA oruga (ver motion.pivot);
        # "back" = la oruga que se mueve va hacia atrás
        speed = cfg.P["v_turn_max"]
        if "back" in step[2:]:
            speed = -speed
        return motion.pivot(motion.wrap180(map_target(step[1]) - hal.heading()), speed)
    if kind == "goto":
        # ("goto", x, y[, vel]): ir a ese punto del mapa con odometría encoders + giroscopio
        speed = val(step[3]) if len(step) > 3 else cfg.P["v_slow"]
        return odo.goto(step[1], step[2], speed)
    if kind == "edge":
        # ("edge", color, vel, max_cm[, rumbo]): recto hasta salir de la zona de ese color
        target = map_target(step[4]) if len(step) > 4 else None
        return motion.drive_to_edge(step[1], val(step[2]), val(step[3]), target)
    if kind == "cross":
        # ("cross", vel, max_cm[, rumbo]): recto hasta una línea que cruza el camino
        target = map_target(step[3]) if len(step) > 3 else None
        if target is not None:
            motion.turn_to(target)
        return motion.drive_to_cross(val(step[1]), val(step[2]), target)
    if kind == "seek":
        speed = val(step[1]) if len(step) > 1 else cfg.P["v_slow"]
        max_cm = val(step[2]) if len(step) > 2 else 60
        target = None
        if len(step) > 3:                      # rumbo de mapa opcional
            target = map_target(step[3])
            motion.turn_to(target)
        return motion.seek_line(speed, max_cm, target)
    if kind == "spin":
        return motion.spin_to_line(step[1])

    if kind == "approach_ped":
        return approach_pedestal(step[1], step[2])
    if kind == "approach_obj":
        return approach_object(step[1], step[2])
    if kind == "retreat":
        return motion.straight(-last_advance, cfg.P["v_slow"])
    if kind == "to_tower":
        return to_tower()
    if kind == "climb":
        return motion.climb()
    if kind == "line_ref":
        # ("line_ref", rumbo, cond, vel, timeout): sigue la línea hasta cond PROMEDIANDO el rumbo;
        # al terminar, ese promedio es "rumbo" de mapa. En una recta el seguidor oscila y una sola
        # lectura tenía ~4° de error; el promedio da la dirección de la línea.
        cond = make_cond(step[2])
        acc = [0.0, 0]

        def cond2(bits, j):
            acc[0] += hal.heading()
            acc[1] += 1
            return cond(bits, j)
        ok = lf.follow_until(cond2, val(step[3]), step[4])
        if acc[1] > 0:
            heading_ref = step[1] - acc[0] / acc[1]
        return ok
    if kind == "if_placed":
        if not placed:
            return True
        for sub in step[1]:
            if not run_step(sub):
                return False
        return True
    if kind in ("if_skipped", "if_ran"):
        # ("if_skipped", id, [pasos]): la misión id se saltó en esta pasada (ya estaba hecha y el
        # robot fue recolocado): pasos para llegar a donde ella lo habría dejado.
        # ("if_ran", id, [pasos]): la misión id sí se corrió en esta pasada.
        hit = step[1] in (pass_skipped if kind == "if_skipped" else pass_ran)
        if not hit:
            return True
        for sub in step[2]:
            if not run_step(sub):
                return False
        return True
    if kind == "if_start":
        if step[1] != run_level:
            return True
        for sub in step[2]:
            if not run_step(sub):
                return False
        return True
    if kind == "crest":
        # ("crest", cm[, rumbo[, color[, altura]]]): con color, la referencia es ver ese color
        # arriba; con altura, el brazo va a esa altura en ese momento sin detenerse;
        # con rumbo de mapa, sube sosteniéndolo con el IMU (escalera de
        # dos tramos: cada oruga debe ir sobre el suyo)
        target = None
        if len(step) > 2:
            target = map_target(step[2])
            motion.turn_to(target)
        color = step[3] if len(step) > 3 else None
        arm_h = val(step[4]) if len(step) > 4 else None
        return motion.climb_crest(val(step[1]), target=target, color=color, arm_h=arm_h)
    if kind == "stairs":
        return motion.stairs(val(step[1]) if len(step) > 1 else None)
    if kind == "claw":
        gripper.claw(val(step[1]))
        return True
    if kind == "arm":
        gripper.arm_to(val(step[1]))
        return True
    if kind == "hold":
        return gripper.hold()
    if kind == "detour":
        return motion.detour(step[1])
    if kind == "cards":
        # ("cards"[, retroceso cm]): primero retrocede leyendo (tarjetas que quedaron atrás)
        return scan_cards(val(step[1]) if len(step) > 1 else 0)
    if kind == "drop_red":
        return drop_red()
    if kind == "stop_in":
        return stop_in(step[1])
    if kind == "wait":
        hal.wait(step[1])
        return True
    raise ValueError("paso desconocido: %s" % kind)


def run_mission(m):
    hal.show("M%d %s" % (m["id"], m["name"]), line=1)
    for step in m["steps"]:
        if hal.abort_requested():
            return False
        if not run_step(step):
            return False
    return True


def run(start_level=1, budget_s=None, t_start=None, skip=None):
    """Corre el TRAMO que empieza en start_level. Devuelve los puntos estimados.

    Con cfg.SEGMENTS el robot se detiene al terminar el tramo (misión con "end_level") o al
    fallar una misión crítica; next_level queda con el nivel que conviene elegir después.
    skip: misiones ya logradas en este encendido; solo se saltan las de manipulación (las de
    navegación, críticas, se repiten porque llevan al robot a donde empieza la siguiente)."""
    global run_level, placed, next_level, current_level
    if budget_s is None:
        budget_s = cfg.AUTO_BUDGET_S
    if t_start is None:
        t_start = hal.now()
    reset_state()
    run_level = start_level
    next_level = start_level
    placed = True
    crit = {}
    for m in ms.MISSIONS:
        crit[m["id"]] = m["critical"]
    done = set()
    for mid in (skip or ()):
        if not crit.get(mid, True):
            done.add(mid)
    points = 0
    pass_skipped.clear()
    pass_ran.clear()
    for m in ms.MISSIONS:
        if m["level"] < start_level:
            continue
        if m["id"] in done:
            pass_skipped.add(m["id"])
            continue
        if hal.now() - t_start >= budget_s or hal.abort_requested():
            break
        pass_ran.add(m["id"])
        current_level = m["level"]
        ok = run_mission(m)
        placed = False
        results.append((m["id"], ok))
        hal.stop()
        if ok:
            done.add(m["id"])
            completed.add(m["id"])
            points += m["pts"]
            hal.leds(0, 80, 0)
            hal.show("Pts aprox: %d" % points, line=2)
            if m.get("end_level") and cfg.SEGMENTS:
                next_level = m["level"] + 1
                break
            if m is ms.MISSIONS[-1]:
                next_level = 5              # terminó todo: la pantalla vuelve a leer la zona
        else:
            hal.leds(80, 0, 0)
            if hal.abort_requested() or m["critical"]:
                break
    hal.stop()
    return points


# ---------------------------------------------------------------- elegir nivel de inicio
def detect_level():
    """Lee el color de la zona de inicio bajo el robot (rojo/amarillo/azul/verde)."""
    for probe in ("L1", "R1"):
        lvl = colors.zone_level(colors.read_stable(probe))
        if lvl:
            return lvl
    return 1


def choose_level(level=None):
    """Pantalla de inicio del autónomo. Joystick: elige el nivel (cfg.LEVEL_KEYS: arriba 1,
    abajo 2, izquierda 3, derecha 4). START_BUTTON (B): arrancar el tramo. Centro del joystick:
    menú de ajustes. Devuelve el nivel, o 0 = ajustes."""
    if level is None:
        level = detect_level()
    hal.wait(0.3)
    while True:
        hal.show("Nivel %d" % level, line=0)
        hal.show("^1 v2 <3 >4  %s=GO" % cfg.START_BUTTON.upper(), line=1)
        hal.show("%s=parar  centro=ajustes" % cfg.ABORT_BUTTON.upper(), line=2)
        for key in cfg.LEVEL_KEYS:
            if hal.button(key):
                level = cfg.LEVEL_KEYS[key]
        if hal.button(cfg.START_BUTTON):
            while hal.button(cfg.START_BUTTON):     # que no cuente como otro botón al soltarlo
                hal.wait(0.02)
            return level
        if hal.button(cfg.MENU_BUTTON):
            return 0
        hal.wait(0.02)
